INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('cmo-daily-cadence', 'cmo-content', 'Daily Content Cadence Check', 'Check content scheduled for today, review overnight engagement, check campaign progress', 'cron', '0 8 * * *', 'custom_prompt', '{"prompt":"Execute Daily Content Cadence Check. Step 1: Query content_pipeline for items scheduled to publish today. Step 2: Check social media engagement from yesterday''s posts using platform engagement tools. Step 3: Review active campaign progress — are campaigns on track? Step 4: Check content_pipeline for items in ''Writing'' or ''Editing'' stages needing attention. Step 5: Cross-reference with activity_log for content creation time correlation. Produce: 1) Today''s publishing schedule — items, platforms, times, 2) Overnight engagement summary — top performing posts, notable responses, 3) Campaign progress update — active campaigns, metrics vs targets, 4) Content creation priorities — items needing work today. If no content scheduled and no engagement signals: reply HEARTBEAT_OK. If content publishing or engagement detected: produce brief with key metrics.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cmo-weekly-review', 'cmo-content', 'Weekly Content Performance Review', 'Weekly content performance analysis with platform breakdown and pipeline health', 'cron', '0 17 * * 0', 'custom_prompt', '{"prompt":"Execute Weekly Content Performance Review. Step 1: Query content_pipeline with period=past_week for all published content. Step 2: Analyze performance by platform — reach, engagement, conversion rates. Step 3: Review content pipeline health — count items by stage (Idea, Writing, Editing, Scheduled, Published). Step 4: Check campaign metrics vs targets for active campaigns. Step 5: Identify content gaps for next week — what platforms/formats are underrepresented? Step 6: Cross-reference with quarterly_goals for content OKR progress. Produce: 1) Weekly content report — pieces published, total reach, engagement rate by platform, 2) Pipeline health — items by stage, bottlenecks identified, 3) Campaign performance — metrics vs targets, 4) Next week recommendations — content gaps, optimal posting schedule, 5) Top performer analysis — what worked best this week. Save weekly content summary to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If weekly engagement declining 3+ consecutive weeks or content output below 50% of target → send message.send to ceo-strategic with content pattern flag. Do NOT write to systemic_journal.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cmo-monthly-synthesis', 'cmo-content', 'Monthly Content Synthesis', 'Monthly content synthesis with waterfall effectiveness and ROI calculation', 'cron', '0 15 L * *', 'custom_prompt', '{"prompt":"Execute Monthly Content Synthesis. Step 1: Query content_pipeline with period=past_month for comprehensive monthly data. Step 2: Calculate aggregate metrics — total reach, engagement rate, conversion rate, viral score distribution. Step 3: Analyze content-waterfall effectiveness — how well was content repurposed across platforms? Step 4: Calculate content ROI — reach/engagement vs time invested (from activity_log). Step 5: Review campaign ROI — campaign spend vs revenue generated (from financial_log context). Step 6: Generate monthly content performance report. Produce: 1) Monthly content report — total pieces, total reach, engagement rate, conversion rate, 2) Platform performance breakdown — which platforms drove most value, 3) Content-waterfall efficiency — repurposing rate across platforms, 4) Content ROI analysis — value generated vs time invested, 5) Month-over-month trends — growth rates, engagement trajectory. Save comprehensive monthly content report to reports DB via lifeos_create_report. SYSTEMIC FLAG CHECK: If monthly engagement declining, or content ROI negative for 2+ consecutive months, or audience erosion detected → send message.send to ceo-strategic with systemic content pattern flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('cmo-quarterly-strategy', 'cmo-content', 'Quarterly Content Strategy Review', 'Quarterly content strategy review with OKR progress and strategic pivots', 'cron', '0 13 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Content Strategy Review. Step 1: Query content_pipeline with period=past_quarter for comprehensive quarterly data. Step 2: Assess quarterly content OKR progress — compare targets vs actuals for reach, engagement, content volume. Step 3: Analyze quarter-over-quarter trends — audience growth, engagement trends, viral content patterns. Step 4: Review content theme performance — which themes resonated, which fell flat? Step 5: Identify strategic pivots for next quarter — content gaps, platform shifts, format changes. Step 6: Generate strategic content posture assessment — brand alignment, competitive positioning, growth trajectory. Produce: 1) Quarterly content report — OKR achievement %, key metrics, trend direction, 2) Content theme analysis — top performing themes, underperforming themes, 3) Platform strategy assessment — which platforms to double down on, which to reduce, 4) Strategic recommendations for next quarter — content priorities, platform shifts, budget allocation, 5) Brand alignment check — content supporting annual/quarterly goals. Save comprehensive quarterly content report to reports DB. SYSTEMIC FLAG CHECK: If content strategy misaligned with quarterly goals, or brand risk detected, or engagement declining quarter-over-quarter → send message.send to ceo-strategic with critical content strategy flag.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
